 Test("original and replacement artwork keep full same-aspect viewport",()=>{foreach(var size in new[]{(1672,941),(3344,1882)}){var r=SeasideMenuLayout.ArtworkPixels(size.Item1,size.Item2);Near(r.X,0);Near(r.Y,0);Near(r.Width,size.Item1);Near(r.Height,size.Item2);}});
