 Test("motion starts and stays neutral without selection",()=>{var m=new SeasideButtonMotion();for(int i=0;i<1000;i++)Check(!m.Advance(.02,false));Check(m.Pose==SeasideButtonPose.Neutral);});
 Test("hover period has bounded translation and rotation with no scale pulse",()=>{var m=new SeasideButtonMotion();double peak=0;for(int i=0;i<1200;i++){m.Advance(.01,true);Check(Math.Abs(m.Pose.X)<=1.20001&&Math.Abs(m.Pose.Rotation)<=.65001);Near(m.Pose.ScaleX,1);Near(m.Pose.ScaleY,1);peak=Math.Max(peak,Math.Abs(m.Pose.X));}Check(peak>1.19);});
 Test("deselection settles to the exact neutral pose",()=>{var m=new SeasideButtonMotion();for(int i=0;i<30;i++)m.Advance(.02,true);for(int i=0;i<10;i++)m.Advance(.02,false);Check(m.Pose==SeasideButtonPose.Neutral);});
 Test("press peak is four pixels down and 97 by 95 percent scale",()=>{var m=new SeasideButtonMotion();Check(m.BeginPress());for(int i=0;i<6;i++)Check(!m.Advance(.02,true));Near(m.Pose.X,0);Near(m.Pose.Y,-4);Near(m.Pose.Rotation,0);Near(m.Pose.ScaleX,.97);Near(m.Pose.ScaleY,.95);});
 Test("press completes once and returns to neutral before action signal",()=>{var m=new SeasideButtonMotion();m.BeginPress();int count=0;for(int i=0;i<50;i++)if(m.Advance(.01,false))count++;Check(count==1&&!m.Pressing&&m.Pose==SeasideButtonPose.Neutral);});
 Test("repeated presses cannot restart a pending press",()=>{var m=new SeasideButtonMotion();m.BeginPress();m.Advance(.06,true);Check(!m.BeginPress());m.Advance(.06,true);Near(m.Pose.Y,-4);});
 Test("invalid time deltas cannot produce NaN or trigger completion",()=>{var m=new SeasideButtonMotion();m.BeginPress();foreach(var d in new[]{double.NaN,double.PositiveInfinity,double.NegativeInfinity,-1d,0d})Check(!m.Advance(d,true));Check(m.Pose==SeasideButtonPose.Neutral&&m.Pressing);});
 Test("one stalled frame cannot skip the whole press feedback",()=>{var m=new SeasideButtonMotion();m.BeginPress();Check(!m.Advance(10,true));Check(m.Pressing&&m.Pose.Y<0);});
 Test("thousand resets never accumulate movement or scale",()=>{var m=new SeasideButtonMotion();for(int i=0;i<1000;i++){m.Advance(.05,true);m.BeginPress();m.Advance(.04,false);m.Reset();Check(m.Pose==SeasideButtonPose.Neutral&&!m.Pressing);}});
